# --- SonrisaHostingExtensions.cs --------------------------------------------
$hosting = @'
using Microsoft.Extensions.Hosting;
using Serilog;

namespace SonrisaNews.Shared.Hosting;

/// <summary>
/// Cross-process host defaults. Called from both the API and Worker <c>Program.cs</c>
/// so they emit identical log shapes. Future host-level cross-cutting concerns
/// (ProblemDetails, health checks, CORS) land here too.
/// </summary>
public static class SonrisaHostingExtensions
{
    /// <summary>
    /// Wires Serilog with the same configuration shape for the API and the Worker.
    /// Reads from <c>Serilog</c> in <c>appsettings.json</c>, enriches with <c>FromLogContext</c>,
    /// and writes structured JSON to the console (one event per line, invariant culture).
    /// </summary>
    public static IHostBuilder UseSonrisaNewsSerilog(this IHostBuilder builder) =>
        builder.UseSerilog((context, services, configuration) => configuration
            .ReadFrom.Configuration(context.Configuration)
            .ReadFrom.Services(services)
            .Enrich.FromLogContext()
            .WriteTo.Console(formatProvider: System.Globalization.CultureInfo.InvariantCulture));
}
'@

# --- ApplicationClockServiceCollectionExtensions.cs -------------------------
$clock = @'
using Microsoft.Extensions.DependencyInjection;

namespace SonrisaNews.Shared.Hosting;

/// <summary>DI registration for <see cref="IClock"/>. Shared by the API and Worker.</summary>
public static class ApplicationClockServiceCollectionExtensions
{
    /// <summary>
    /// Registers the UTC clock as a singleton. <see cref="IClock"/> is stateless and
    /// thread-safe; a single instance is shared by all consumers.
    /// </summary>
    public static IServiceCollection AddSonrisaNewsClock(this IServiceCollection services) =>
        services.AddSingleton<IClock, SystemClock>();
}
'@

